const d = $('Campaign For Review Webhook').first().json.body;
const retail = parseFloat(d.retail_price ?? 0);
const wholesale = parseFloat(d.wholesale_cost ?? 0);
const profit = (retail - wholesale).toFixed(2);

const message = `*NEW CAMPAIGN REQUEST*

Tech: @${d.username}
Product: ${d.product_name}
Wholesale: $${parseFloat(d.wholesale_cost).toFixed(2)}
Retail: $${parseFloat(d.retail_price).toFixed(2)}
Profit/unit: $${profit}
Goal: ${d.goal_units} units
Link: pagefairy.me/${d.username}`;

const inline_keyboard = [[
  { text: '✅ Approve', callback_data: `approve_${d.campaign_id}` },
  { text: '❌ Reject', callback_data: `reject_${d.campaign_id}` }
]];

return [{ json: { message, inline_keyboard, campaign_id: d.campaign_id } }];
